    reportSearchQuery: '',
    reportSortColumn: null,
    reportSortDirection: 'desc',
    rejectedSearchQuery: '',
    rejectedSortColumn: null,
    rejectedSortDirection: 'desc',
    reportMonth: null, reportYear: null,
    invoiceYear: null,
