  /* =========================================================
     UTILITIES
  ========================================================== */
  function fmtMoney(n){ n = isFinite(n)?n:0; var neg = n<0; n=Math.abs(n); var s='$'+n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}); return neg? '-'+s : s; }
  var CURRENCY_GROUPS = [
    {label: null, items: ['SGD']},
    {label: 'ASEAN', items: ['BND','KHR','IDR','LAK','MYR','MMK','PHP','THB','VND']},
    {label: 'Asia', items: ['CNY','HKD','INR','JPY','KRW','TWD','PKR','BDT','LKR','AED','SAR','ILS']},
    {label: 'Rest of World', items: ['USD','EUR','GBP','AUD','NZD','CAD','CHF','ZAR']}
  ];
  function renderCurrencyOptions(selected){
    selected = selected || 'SGD';
    var html = '';
    CURRENCY_GROUPS.forEach(function(group){
      var optsHtml = group.items.map(function(cur){
        return '<option value="'+cur+'" '+(cur===selected?'selected':'')+'>'+cur+'</option>';
      }).join('');
      html += group.label ? ('<optgroup label="'+group.label+'">'+optsHtml+'</optgroup>') : optsHtml;
    });
    return html;
  }
  function fmtCurrencyAmount(currency, amount){
    var n = Number(amount)||0;
    return (currency||'SGD')+' '+n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
  }

  function claimMatchesSearch(c, query, includeEmployee){
    if(!query) return true;
    var q = query.trim().toLowerCase();
    if(!q) return true;
    var haystack = [c.category, c.vendor, c.status, c.currency].filter(Boolean).join(' ').toLowerCase();
    if(includeEmployee){ haystack += ' ' + employeeName(c.employee_id).toLowerCase(); }
    return haystack.indexOf(q) !== -1;
  }

  var EXCHANGE_RATE_CACHE = {};
  var EXCHANGE_RATE_CACHE_MS = 60*60*1000;
  function withTimeout(promise, ms, label){
    return new Promise(function(resolve, reject){
      var settled = false;
      var timer = setTimeout(function(){
        if(settled) return;
        settled = true;
        reject(new Error((label||'Request')+' timed out after '+ms+'ms - the server may be slow or unreachable.'));
      }, ms);
      promise.then(function(v){
        if(settled) return;
        settled = true;
        clearTimeout(timer);
        resolve(v);
      }, function(err){
        if(settled) return;
        settled = true;
        clearTimeout(timer);
        reject(err);
      });
    });
  }

  // A brief WiFi hiccup, a stale keep-alive connection, or (on Safari) a
  // content blocker occasionally causes the very FIRST network request in a
  // while to fail outright before it ever reaches the server -- the retry
  // almost always succeeds immediately since the browser opens a fresh
  // connection. Without this, a user hits "Load failed" on login/signup/
  // forgot-password/submit-claim and has to re-type the whole form just to
  // try again. This distinguishes that from a REAL error (wrong password,
  // "already registered", a validation message) which must never be retried
  // -- retrying those would just waste time and show the same real error twice.
  var TRANSIENT_NETWORK_ERROR_RE = /load failed|failed to fetch|network connection was lost|networkerror|network request failed|internet connection appears to be offline|err_network|err_internet_disconnected|err_connection|access control checks/i;
  function isTransientNetworkError(err){
    var msg = (err && (err.message || err.error_description)) || err || '';
    return TRANSIENT_NETWORK_ERROR_RE.test(String(msg));
  }
  // fn is a factory returning a fresh promise each call (Supabase-style
  // {data,error} result, or a thrown/rejected error). On a transient network
  // failure -- whether it shows up as a resolved {error:...} (how Supabase
  // normally reports it) or an outright rejection -- waits briefly and calls
  // fn() again exactly once before giving up, via the `retried` flag below,
  // so a real, repeatable failure still surfaces to the user normally.
  function withNetworkRetry(fn){
    var retried = false;
    function handle(res){
      if(res && res.error && !retried && isTransientNetworkError(res.error)){
        retried = true;
        return new Promise(function(resolve){ setTimeout(resolve, 700); }).then(fn).then(handle, onError);
      }
      return res;
    }
    function onError(err){
      if(!retried && isTransientNetworkError(err)){
        retried = true;
        return new Promise(function(resolve){ setTimeout(resolve, 700); }).then(fn).then(handle, onError);
      }
      throw err;
    }
    return fn().then(handle, onError);
  }

  function fetchRateFrankfurter(currency){
    return fetch('https://api.frankfurter.app/latest?from='+encodeURIComponent(currency)+'&to=SGD')
      .then(function(res){ if(!res.ok) throw new Error('Frankfurter returned '+res.status); return res.json(); })
      .then(function(data){
        var rate = data && data.rates && data.rates.SGD;
        if(!rate || isNaN(rate)) throw new Error('Frankfurter has no SGD rate for '+currency);
        return rate;
      });
  }
  function fetchRateOpenERApi(currency){
    return fetch('https://open.er-api.com/v6/latest/'+encodeURIComponent(currency))
      .then(function(res){ if(!res.ok) throw new Error('open.er-api returned '+res.status); return res.json(); })
      .then(function(data){
        var rate = data && data.rates && data.rates.SGD;
        if(!rate || isNaN(rate)) throw new Error('open.er-api has no SGD rate for '+currency);
        return rate;
      });
  }
  function getExchangeRateToSGD(currency){
    if(!currency || currency==='SGD') return Promise.resolve(1);
    var cached = EXCHANGE_RATE_CACHE[currency];
    if(cached && (Date.now()-cached.at) < EXCHANGE_RATE_CACHE_MS){
      return Promise.resolve(cached.rate);
    }
    return fetchRateFrankfurter(currency).catch(function(err1){
      console.error('Frankfurter rate lookup failed', err1);
      return fetchRateOpenERApi(currency).catch(function(err2){
        console.error('open.er-api rate lookup failed', err2);
        var combined = new Error('Both rate providers failed for '+currency+' - ('+err1.message+') / ('+err2.message+')');
        throw combined;
      });
    }).then(function(rate){
      EXCHANGE_RATE_CACHE[currency] = {rate:rate, at:Date.now()};
      return rate;
    });
  }

  function fmtDate(d){ if(!d) return '-'; var dt=new Date(d+'T00:00:00'); if(isNaN(dt)) return d; return dt.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}); }
  function fmtDateTime(iso){ if(!iso) return '-'; var dt=new Date(iso); if(isNaN(dt)) return iso; return dt.toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}); }
  function escapeHtml(str){ return String(str==null?'':str).replace(/[&<>"']/g, function(s){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]; }); }
  function todayStr(){ return new Date().toISOString().slice(0,10); }
  function yearStartStr(){ return new Date().getFullYear()+'-01-01'; }
  function isImageName(name){ return /\.(png|jpe?g|gif|webp|heic|heif|bmp)$/i.test(name||''); }

  function profileById(id){ return STATE.profiles.filter(function(p){ return p.id===id; })[0]; }
  function employeeName(id){ var p = profileById(id); return p ? p.name : 'Unknown'; }
  function familyMemberById(id){ return STATE.familyMembers.filter(function(m){ return m.id===id; })[0]; }
  function myFamilyMembers(){
    var email = STATE.profile && STATE.profile.email;
    return STATE.familyMembers.filter(function(m){ return m.employee_email===email; });
  }
  function claimantLabel(c){
    if(!c.family_member_id) return 'Self';
    var m = familyMemberById(c.family_member_id);
    return m ? (escapeHtml(m.name)+' <span class="tiny muted">('+escapeHtml(m.relationship)+')</span>') : 'Family member';
  }

  function vendorSuggestions(){
    var seen = {}; var list = [];
    STATE.claims.forEach(function(c){
      var v = c.vendor && c.vendor.trim();
      if(v && !seen[v.toLowerCase()]){ seen[v.toLowerCase()]=true; list.push(v); }
    });
    return list.sort(function(a,b){ return a.localeCompare(b); });
  }
  function renderVendorDatalist(id){
    return '<datalist id="'+id+'">'+vendorSuggestions().map(function(v){ return '<option value="'+escapeHtml(v)+'"></option>'; }).join('')+'</datalist>';
  }

  function claimCutoffNotice(){
    var monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    var now = new Date();
    var year = now.getFullYear();
    var month = now.getMonth();
    var cutoff = new Date(year, month, 25, 23, 59, 59, 999);
    var cutoffLabel = '25 ' + monthNames[month].slice(0,3) + ' ' + year + ', 23:59';
    if(now <= cutoff){
      return 'Submit by ' + cutoffLabel + ' to have this claim processed in ' + monthNames[month] + '. Submissions after this cutoff will be processed the following month.';
    }
    var nextMonthIdx = (month + 1) % 12;
    var nextMonthYear = month === 11 ? year + 1 : year;
    return 'This month\'s cutoff (' + cutoffLabel + ') has passed. Claims submitted now will be processed in ' + monthNames[nextMonthIdx] + ' ' + nextMonthYear + '.';
  }

  function captureClaimFormValues(){
    var form = document.querySelector('form[data-form="submit-claim"]');
    if(!form) return null;
    return {
      category: form.category ? form.category.value : '',
      vendor: form.vendor ? form.vendor.value : '',
      amount: form.amount ? form.amount.value : '',
      receiptDate: form.receiptDate ? form.receiptDate.value : ''
    };
  }
  function restoreClaimFormValues(vals){
    var form = document.querySelector('form[data-form="submit-claim"]');
    if(!form || !vals) return;
    if(form.category && vals.category){ form.category.value = vals.category; }
    if(form.vendor && vals.vendor){ form.vendor.value = vals.vendor; }
    if(form.amount && vals.amount){ form.amount.value = vals.amount; }
    if(form.receiptDate && vals.receiptDate){ form.receiptDate.value = vals.receiptDate; }
  }

  /* =========================================================
     BUSINESS LOGIC
  ========================================================== */
  function sgdAmountOf(c){
    return Number(c.amount_sgd != null ? c.amount_sgd : c.amount) || 0;
  }

  function computeWallet(employeeId){
    var profile = profileById(employeeId) || {annual_allocation:0};
    var currentYear = new Date().getFullYear();
    var empClaims = STATE.claims.filter(function(c){
      return c.employee_id===employeeId && new Date(c.receipt_date+'T00:00:00').getFullYear()===currentYear;
    });
    var approvedTotal=0, pendingTotal=0;
    var byCategory = {};
    STATE.benefits.forEach(function(b){ byCategory[b] = {approved:0, pending:0}; });
    empClaims.forEach(function(c){
      var amt = sgdAmountOf(c);
      if(!byCategory[c.category]) byCategory[c.category] = {approved:0, pending:0};
      if(c.status==='approved'){ approvedTotal+=amt; byCategory[c.category].approved+=amt; }
      if(c.status==='pending'){ pendingTotal+=amt; byCategory[c.category].pending+=amt; }
    });
    // Prorate the wallet cap for an employee's own partial first year, the
    // same way New Hire Invoicing prorates what the client gets billed --
    // reuses proratedAllocationForYear() so the two never drift apart.
    // monthsEmployedInYear() already returns 12 (full year) for any year
    // after the join year on its own, so this naturally reverts to the full
    // annual_allocation from next January without any reset job.
    var allocation = (profile.prorate_entitlement_default!==false)
      ? proratedAllocationForYear(profile, currentYear)
      : (Number(profile.annual_allocation)||0);
    var available = allocation - approvedTotal - pendingTotal;
    var utilizationPct = allocation>0 ? Math.min(100, (approvedTotal/allocation)*100) : 0;
    return {allocation:allocation, approvedTotal:approvedTotal, pendingTotal:pendingTotal, available:available, utilizationPct:utilizationPct, byCategory:byCategory, year:currentYear};
  }

  function buildPeriodReport(claims, startDate, endDate){
    var inRange = function(c){
      var d = new Date(c.receipt_date+'T00:00:00');
      return d>=startDate && d<=endDate;
    };
    var approved = claims.filter(function(c){ return c.status==='approved' && inRange(c); });
    var rejected = claims.filter(function(c){ return c.status==='rejected' && inRange(c); });

    var byCategory={}, byEmployee={}, totalClaimed=0;
    approved.forEach(function(c){
      var amt = sgdAmountOf(c);
      totalClaimed+=amt;
      byCategory[c.category] = byCategory[c.category]||{count:0,total:0};
      byCategory[c.category].count++; byCategory[c.category].total+=amt;
      byEmployee[c.employee_id] = byEmployee[c.employee_id]||{count:0,total:0,name:employeeName(c.employee_id),categories:{}};
      byEmployee[c.employee_id].count++; byEmployee[c.employee_id].total+=amt;
      byEmployee[c.employee_id].categories[c.category] = byEmployee[c.employee_id].categories[c.category]||{count:0,total:0};
      byEmployee[c.employee_id].categories[c.category].count++;
      byEmployee[c.employee_id].categories[c.category].total+=amt;
    });

    var totalRejected = 0;
    var byEmployeeRejected = {};
    var rejectedClaims = rejected.map(function(c){
      var amt = sgdAmountOf(c);
      totalRejected += amt;
      var reasonText = c.reject_reason || '';
      if(c.admin_note){ reasonText += (reasonText ? ' - ' : '') + c.admin_note; }
      reasonText = reasonText || 'No reason given';
      byEmployeeRejected[c.employee_id] = byEmployeeRejected[c.employee_id]||{name:employeeName(c.employee_id),count:0,total:0,reasons:{}};
      byEmployeeRejected[c.employee_id].count++;
      byEmployeeRejected[c.employee_id].total+=amt;
      byEmployeeRejected[c.employee_id].reasons[reasonText] = (byEmployeeRejected[c.employee_id].reasons[reasonText]||0)+1;
      return {
        employeeId: c.employee_id,
        employeeName: employeeName(c.employee_id),
        category: c.category,
        amount: amt,
        reason: reasonText
      };
    });

    return {byCategory:byCategory, byEmployee:byEmployee, totalClaimed:totalClaimed, totalCount:approved.length,
      rejectedClaims:rejectedClaims, byEmployeeRejected:byEmployeeRejected, totalRejectedCount:rejected.length, totalRejectedAmount:totalRejected};
  }

  /* =========================================================
     ANNUAL INVOICE (Headcount Adjustment + Unutilised Credit Note)
     Principle: adjustment = (headcount at 31 Dec - headcount at 1 Jan) / 2,
     charged (or credited if negative) at the configured rate per head per year.
     Any amount not utilised by employees for the year is credited back via
     credit note, as is any negative headcount adjustment. Net amount =
     additional headcount charge minus total credit note.
  ========================================================== */
  function getInvoiceRate(){
    var n = parseFloat(STATE.appSettings && STATE.appSettings.invoice_rate_per_head);
    return isNaN(n) ? 88 : n;
  }

  function getClientCompanyName(){
    var v = STATE.appSettings && STATE.appSettings.client_company_name;
    return (v && String(v).trim()) ? String(v).trim() : 'Client';
  }

  function getSelectedInvoiceYear(){
    var now = new Date();
    return (STATE.invoiceYear!=null) ? STATE.invoiceYear : (now.getFullYear()-1);
  }

  function getClientCode(){
    var name = getClientCompanyName();
    var firstWord = name.trim().split(/\s+/)[0] || 'CLIENT';
    var code = firstWord.toUpperCase().replace(/[^A-Z0-9]/g,'');
    return code || 'CLIENT';
  }

  function padInvoiceSeq(n){
    var s = String(n);
    while(s.length<4){ s = '0'+s; }
    return s;
  }

  // Draws the next invoice number off one shared running counter, used by
  // BOTH the Annual Invoice and every entitlement invoice (New Hire /
  // Promotion / Initial Roster), so numbers interleave in the order
  // invoices are actually issued, all in the same INV-<CLIENTCODE>-#### format.
  // Only ever called from an explicit "Issue" action, never from Preview -
  // previewing an invoice must never consume a real number.
  function nextInvoiceNumber(){
    var nextSeq = parseInt(STATE.appSettings && STATE.appSettings.invoice_sequence_next, 10);
    if(isNaN(nextSeq) || nextSeq<1){ nextSeq = 1; }
    var formatted = 'INV-'+getClientCode()+'-'+padInvoiceSeq(nextSeq);
    return supabase.from('app_settings').upsert([
      {key:'invoice_sequence_next', value:String(nextSeq+1)}
    ], {onConflict:'key'}).then(function(res){
      if(res.error){ showToast('Could not assign invoice number: '+res.error.message, 'error'); throw res.error; }
      STATE.appSettings.invoice_sequence_next = String(nextSeq+1);
      return formatted;
    });
  }

  // Auto-linking for Void + Reissue: finds the invoice a about-to-be-issued
  // invoice should record as superseding, in a given list (annualInvoices or
  // entitlementInvoices) - the most recently voided one matching `matchFn`
  // that no other invoice has already claimed via supersedes_invoice_id.
  // "Most recently voided and not yet claimed" naturally follows a
  // void -> reissue -> void -> reissue chain correctly, always picking up
  // where the last reissue left off.
  function findUnsupersededVoid(list, matchFn){
    var superseded = {};
    (list||[]).forEach(function(x){ if(x.supersedes_invoice_id){ superseded[x.supersedes_invoice_id]=true; } });
    var candidates = (list||[]).filter(function(x){ return x.status==='voided' && matchFn(x) && !superseded[x.id]; });
    candidates.sort(function(a,b){ return (b.voided_at||'').localeCompare(a.voided_at||''); });
    return candidates[0] || null;
  }

  function buildInvoiceYearOptions(){
    var now = new Date();
    var years = {};
    years[now.getFullYear()] = true;
    years[now.getFullYear()-1] = true;
    STATE.profiles.forEach(function(p){ if(p.effective_date){ years[parseInt(p.effective_date.slice(0,4),10)]=true; } });
    STATE.claims.forEach(function(c){ if(c.receipt_date){ years[parseInt(c.receipt_date.slice(0,4),10)]=true; } });
    return Object.keys(years).map(Number).sort(function(a,b){ return b-a; });
  }

  // How many of the 12 months of `year` an employee counts as employed, for
  // the purpose of billing the company. Both ends are prorated by whole
  // calendar months (any day in a month counts as that full month):
  // - New joiners: counted from their effective_date's month (e.g. joining
  //   anytime in July counts as 6 months, Jul-Dec) through December, unless
  //   they also terminate within the same year (see below).
  // - Terminations: counted through their date_of_termination's month (e.g.
  //   leaving anytime in March counts as 3 months, Jan-Mar), starting from
  //   January unless they also joined within the same year.
  // Anyone who joined before this year and has no termination this year (or
  // has neither date on file) counts as a full 12 months.
  function monthsEmployedInYear(p, year){
    var startMonth = 1;
    if(p.effective_date){
      var effYear = Number(p.effective_date.slice(0,4));
      if(effYear === year){ startMonth = Number(p.effective_date.slice(5,7)); }
      else if(effYear > year){ return 0; }
    }
    var endMonth = 12;
    if(p.date_of_termination){
      var termYear = Number(p.date_of_termination.slice(0,4));
      if(termYear === year){ endMonth = Number(p.date_of_termination.slice(5,7)); }
      else if(termYear < year){ return 0; }
    }
    return Math.max(0, endMonth - startMonth + 1);
  }
  function proratedAllocationForYear(p, year){
    var annualAlloc = Number(p.annual_allocation)||0;
    return annualAlloc * (monthsEmployedInYear(p, year)/12);
  }

  /* =========================================================
     ENTITLEMENT INVOICING (New Hire / Promotion / Initial Roster)
     ---------------------------------------------------------
     A separate, ad-hoc invoice (issued whenever, not once a year) that
     bills the client only for entitlement dollars - never the headcount
     adjustment, which stays exclusively on the Annual Invoice. The very
     first one ever issued for this client is automatically the "Initial
     Invoice" (adds a per-pax headcount establishment charge on top);
     every one after that is a plain New Hire / Promotion invoice
     (entitlement only).
  ========================================================== */

  // How many of the remaining months of the year a mid-year promotion's
  // allocation increase (or decrease) should be billed for, counting the
  // effective-date month itself as a full month - same whole-month rule as
  // a new joiner, just measured from the change date instead of a hire date.
  function monthsFromDateToYearEnd(dateStr){
    var month = Number(dateStr.slice(5,7));
    return 12 - month + 1;
  }

  function hasAnyIssuedEntitlementInvoice(){
    return STATE.entitlementInvoices.some(function(inv){ return inv.status==='issued'; });
  }

  // Every issued (non-voided) entitlement-invoice line item that actually
  // billed an employee's base entitlement (new hire or initial-roster type),
  // keyed by employee id + the calendar year it covered. Used both to keep
  // an already-invoiced employee off the pending list, and by the Annual
  // Invoice to know what was actually billed for them instead of guessing.
  function issuedEntitlementItemsByEmployeeYear(){
    var issuedInvoiceIds = {};
    STATE.entitlementInvoices.forEach(function(inv){ if(inv.status==='issued'){ issuedInvoiceIds[inv.id]=inv; } });
    var map = {};
    STATE.entitlementInvoiceItems.forEach(function(item){
      var inv = issuedInvoiceIds[item.invoice_id];
      if(!inv) return;
      if(item.item_type!=='new_hire' && item.item_type!=='initial_roster') return;
      var yr = Number(item.effective_date.slice(0,4));
      var key = item.employee_id+'|'+yr;
      if(!map[key]) map[key] = [];
      map[key].push({item:item, invoice:inv});
    });
    return map;
  }

  // Sum of already-issued promotion line items for an employee in a given
  // year (an employee can have more than one promotion invoiced in a year).
  function issuedPromotionAmountForEmployeeYear(employeeId, year){
    var issuedInvoiceIds = {};
    STATE.entitlementInvoices.forEach(function(inv){ if(inv.status==='issued'){ issuedInvoiceIds[inv.id]=true; } });
    var total = 0;
    STATE.entitlementInvoiceItems.forEach(function(item){
      if(item.item_type!=='promotion') return;
      if(!issuedInvoiceIds[item.invoice_id]) return;
      if(item.employee_id!==employeeId) return;
      if(Number(item.effective_date.slice(0,4))!==year) return;
      total += Number(item.final_amount)||0;
    });
    return total;
  }

  function entitlementSelectionKey(kind, id){ return kind+':'+id; }

  function getEntitlementSelection(key, defaultProrate){
    if(!STATE.entitlementSelections[key]){
      STATE.entitlementSelections[key] = {checked:false, prorate: defaultProrate!==false, prorateManual:false, waiveStatus:'normal', waiveReason:'', overrideAmount:null};
    } else if(!STATE.entitlementSelections[key].prorateManual && defaultProrate!==undefined){
      // Keep this row's Prorate checkbox following the employee's standing
      // setting (Employee Management -> Prorate column) until the admin
      // explicitly overrides it right here on this row - so changing that
      // standing setting shows up in the Amount immediately, the next time
      // this row renders, rather than needing a full page refresh. Once
      // the admin does touch this row's own checkbox (below), it's treated
      // as a deliberate one-time override and stops auto-following.
      STATE.entitlementSelections[key].prorate = defaultProrate!==false;
    }
    return STATE.entitlementSelections[key];
  }

  // The full pending list: employees never yet entitlement-invoiced (new
  // hires), plus allocation increases/decreases awaiting invoicing
  // (promotions). Nothing here is restricted to a single month - it's every
  // outstanding billable event, in effective-date order, and the admin picks
  // whichever subset to include on the next invoice.
  function pendingEntitlementItems(){
    if(!STATE.profiles || !STATE.profile || STATE.profile.role!=='admin') return [];
    var billedMap = issuedEntitlementItemsByEmployeeYear();
    var items = [];
    STATE.profiles.forEach(function(p){
      if(p.role!=='user' || !p.effective_date) return;
      var year = Number(p.effective_date.slice(0,4));
      if(billedMap[p.id+'|'+year]) return; // already invoiced for this year
      var months = monthsEmployedInYear(p, year);
      var prorated = proratedAllocationForYear(p, year);
      var full = Number(p.annual_allocation)||0;
      items.push({
        key: entitlementSelectionKey('hire', p.id),
        type: 'new_hire',
        employeeId: p.id, employeeName: p.name, employeeEmail: p.email,
        effectiveDate: p.effective_date, months: months,
        proratedAmount: prorated, fullAmount: full,
        defaultProrate: p.prorate_entitlement_default!==false
      });
    });
    STATE.allocationChanges.forEach(function(ac){
      if(ac.invoiced) return;
      var delta = Number(ac.new_allocation)-Number(ac.old_allocation);
      var months = monthsFromDateToYearEnd(ac.effective_date);
      var prorated = delta*(months/12);
      var p = profileById(ac.employee_id);
      items.push({
        key: entitlementSelectionKey('promo', ac.id),
        type: 'promotion',
        employeeId: ac.employee_id, employeeName: p?p.name:'(former employee)', employeeEmail: p?p.email:'',
        effectiveDate: ac.effective_date, months: months,
        proratedAmount: prorated, fullAmount: delta,
        allocationChangeId: ac.id, oldAllocation: Number(ac.old_allocation), newAllocation: Number(ac.new_allocation)
      });
    });
    items.sort(function(a,b){ return a.effectiveDate.localeCompare(b.effectiveDate); });
    return items;
  }

  // "Money Holding" / 80% utilisation check for New Hire Invoicing --------
  // The client doesn't need to be re-invoiced the instant a mid-year new
  // hire or promotion happens - only once the cash LTP is already holding
  // on their behalf has been drawn down to the point where 80% or more of
  // the company's total planned entitlement commitment has been utilised
  // (i.e. Money Holding has fallen to 20% or less of that planned total).
  // This is purely a reminder threshold - it never blocks issuing an
  // invoice manually at any time, at any utilisation level.

  // annual_allocation is a live figure: saveAlloc()/confirmPromotion() write
  // it onto the profile the instant a new hire is added or a promotion is
  // confirmed, regardless of whether either has actually been invoiced yet.
  // So simply summing it across every currently active employee already
  // reflects the full current commitment - mid-year new hires and
  // promotions both included - with no risk of double-counting once
  // they're later billed.
  function totalPlannedEntitlement(){
    var today = todayStr();
    return (STATE.profiles||[]).filter(function(p){
      return p.role==='user' && (!p.effective_date || p.effective_date<=today) && (!p.date_of_termination || p.date_of_termination>=today);
    }).reduce(function(s,p){ return s+(Number(p.annual_allocation)||0); }, 0);
  }

  // Everything actually billed to the client to date (Initial, New Hire and
  // Promotion invoices via entitlement_invoices, plus every issued Annual
  // Invoice's net payable amount), minus everything already paid out to
  // employees via approved claims. This assumes every issued invoice gets
  // paid in full and promptly - there's no "payment received" tracking yet,
  // so a client that pays late or short will make this read a little
  // optimistic until that's built.
  function moneyHoldingBalance(){
    var billedEnt = (STATE.entitlementInvoices||[]).filter(function(i){ return i.status==='issued'; })
      .reduce(function(s,i){ return s+(Number(i.total_amount)||0); }, 0);
    var billedAnnual = (STATE.annualInvoices||[]).filter(function(i){ return i.status==='issued'; })
      .reduce(function(s,i){ return s+(Number(i.invoice_payable_amount)||0); }, 0);
    var paidOut = (STATE.claims||[]).filter(function(c){ return c.status==='approved'; })
      .reduce(function(s,c){ return s+sgdAmountOf(c); }, 0);
    return billedEnt + billedAnnual - paidOut;
  }

  // The single source of truth both the New Hire Invoicing badges and its
  // transparency panel read from, so the figures shown always match the
  // figures the reminder is actually based on.
  function entitlementCushionStatus(){
    var holding = moneyHoldingBalance();
    var planned = totalPlannedEntitlement();
    // Utilisation: how much of the total planned entitlement has already
    // been drawn down out of what LTP is holding for the client. 0% means
    // the full planned amount is still sitting in the float; 100% would
    // mean it's completely exhausted. Clamped to 0 so a holding balance
    // that's actually ahead of the plan never shows as negative utilisation.
    var utilisation = planned>0 ? Math.max(0, (planned-holding)/planned) : 0;
    var pendingCount = pendingEntitlementItems().length;
    var belowThreshold = planned>0 && utilisation>=0.8;
    return {
      holding:holding, planned:planned, utilisation:utilisation, belowThreshold:belowThreshold,
      // 0 whenever there's nothing to invoice, even at 80%+ utilisation -
      // the reminder is about the backlog below, not the utilisation alone.
      reminderCount: (belowThreshold && pendingCount) ? pendingCount : 0
    };
  }

  // Applies this item's Prorate checkbox and any Waive/Override choice to
  // get the amount that will actually be billed.
  function finalAmountForSelection(item, sel){
    var base = sel.prorate ? item.proratedAmount : item.fullAmount;
    if(sel.waiveStatus==='waived') return 0;
    if(sel.waiveStatus==='custom' && sel.overrideAmount!=null && !isNaN(sel.overrideAmount)) return Number(sel.overrideAmount);
    return base;
  }

  // Builds the live Preview: every currently-checked pending item, the
  // per-pax establishment charge (only if this will be the client's very
  // first entitlement invoice), and the totals. Nothing here is saved -
  // Issue is the only action that writes anything.
  function computeEntitlementInvoicePreview(){
    var pending = pendingEntitlementItems();
    var isInitial = !hasAnyIssuedEntitlementInvoice();
    var rate = getInvoiceRate();
    var lines = [];
    var headcountForPax = 0;
    pending.forEach(function(item){
      var sel = getEntitlementSelection(item.key, item.defaultProrate);
      if(!sel.checked) return;
      var finalAmount = finalAmountForSelection(item, sel);
      var usedProrate = sel.waiveStatus==='normal' ? sel.prorate : sel.prorate; // prorate flag still recorded even if waived/overridden
      if(item.type==='new_hire' || item.type==='initial_roster') headcountForPax++;
      lines.push({
        item:item, selection:sel, finalAmount:finalAmount,
        calculatedAmount: sel.prorate ? item.proratedAmount : item.fullAmount
      });
    });
    var entitlementTotal = lines.reduce(function(s,l){ return s+l.finalAmount; }, 0);
    var perPaxTotal = isInitial ? headcountForPax*rate : 0;
    return {
      invoiceType: isInitial ? 'initial' : 'new_hire',
      lines: lines, rate: rate,
      headcountForPax: headcountForPax, perPaxTotal: perPaxTotal,
      entitlementTotal: entitlementTotal,
      totalAmount: entitlementTotal + perPaxTotal
    };
  }

  function issueEntitlementInvoice(){
    var preview = computeEntitlementInvoicePreview();
    if(!preview.lines.length){ showToast('Select at least one employee or promotion to invoice.', 'error'); return Promise.resolve(); }
    // Auto-link Void + Reissue: if there's a voided entitlement invoice with
    // no successor yet, this new one is presumed to be its correction.
    var precedingVoided = findUnsupersededVoid(STATE.entitlementInvoices, function(){ return true; });
    return nextInvoiceNumber().then(function(invoiceNumber){
      var header = {
        invoice_number: invoiceNumber, invoice_type: preview.invoiceType, status:'issued',
        issued_by: STATE.session.user.id, entitlement_total: preview.entitlementTotal,
        per_pax_rate: preview.invoiceType==='initial' ? preview.rate : null,
        per_pax_total: preview.perPaxTotal, total_amount: preview.totalAmount,
        supersedes_invoice_id: precedingVoided ? precedingVoided.id : null
      };
      return supabase.from('entitlement_invoices').insert([header]).select().then(function(res){
        if(res.error || !res.data || !res.data[0]){ showToast('Could not create invoice: '+(res.error&&res.error.message), 'error'); throw res.error; }
        var invoiceRow = res.data[0];
        var itemRows = preview.lines.map(function(l){
          return {
            invoice_id: invoiceRow.id, employee_id: l.item.employeeId, employee_name: l.item.employeeName,
            employee_email: l.item.employeeEmail, item_type: l.item.type, effective_date: l.item.effectiveDate,
            months_billed: l.item.months, calculated_amount: l.calculatedAmount, prorated: l.selection.prorate,
            waived: l.selection.waiveStatus==='waived', waived_reason: l.selection.waiveStatus!=='normal' ? l.selection.waiveReason : null,
            override_amount: l.selection.waiveStatus==='custom' ? l.selection.overrideAmount : null,
            final_amount: l.finalAmount, allocation_change_id: l.item.allocationChangeId || null,
            per_pax_charge: (invoiceRow.invoice_type==='initial' && (l.item.type==='new_hire'||l.item.type==='initial_roster')) ? preview.rate : null
          };
        });
        return supabase.from('entitlement_invoice_items').insert(itemRows).select().then(function(res2){
          if(res2.error){ showToast('Invoice header saved but line items failed: '+res2.error.message, 'error'); throw res2.error; }
          var savedItems = res2.data || [];
          // Mark any invoiced promotions so they drop off the pending list.
          var promoUpdates = preview.lines.filter(function(l){ return l.item.type==='promotion'; }).map(function(l){
            var savedItem = savedItems.filter(function(si){ return si.allocation_change_id===l.item.allocationChangeId; })[0];
            return supabase.from('allocation_changes').update({invoiced:true, invoice_item_id: savedItem?savedItem.id:null}).eq('id', l.item.allocationChangeId);
          });
          return Promise.all(promoUpdates).then(function(){
            preview.lines.forEach(function(l){ delete STATE.entitlementSelections[l.item.key]; });
            showToast('Invoice '+invoiceNumber+' issued.'+(precedingVoided?(' Supersedes '+precedingVoided.invoice_number+'.'):''), 'success');
            exportEntitlementInvoicePDF({invoiceRow:invoiceRow, items:savedItems, supersedesNumber: precedingVoided?precedingVoided.invoice_number:null});
            return loadAppData();
          });
        });
      });
    }).then(function(){ render(); });
  }

  function voidEntitlementInvoice(id, reason){
    if(!reason || !reason.trim()){ showToast('A reason is required to void an invoice.', 'error'); return Promise.resolve(); }
    return supabase.from('entitlement_invoice_items').select('id').eq('invoice_id', id).then(function(res){
      var itemIds = (res.data||[]).map(function(r){ return r.id; });
      var resetPromo = itemIds.length ? supabase.from('allocation_changes').update({invoiced:false, invoice_item_id:null}).in('invoice_item_id', itemIds) : Promise.resolve();
      return resetPromo.then(function(){
        return supabase.from('entitlement_invoices').update({status:'voided', voided_reason:reason.trim(), voided_at:new Date().toISOString()}).eq('id', id);
      });
    }).then(function(res){
      if(res && res.error){ showToast('Could not void invoice: '+res.error.message, 'error'); return; }
      showToast('Invoice voided.', 'success');
      STATE.voidingInvoice = null; STATE.voidReasonDraft='';
      return loadAppData();
    }).then(function(){ render(); });
  }

  function computeAnnualInvoice(year){
    var startStr = year+'-01-01';
    var endStr = year+'-12-31';
    var rate = getInvoiceRate();

    // An employee with no Effective Date recorded is treated as already
    // employed (rather than excluded) - missing data shouldn't silently drop
    // them from headcount or entitlement totals. Only an explicit
    // Date of Termination excludes them from a given date/period.
    var employedAt = function(p, dateStr){
      return p.role==='user' &&
        (!p.effective_date || p.effective_date<=dateStr) &&
        (!p.date_of_termination || p.date_of_termination>=dateStr);
    };
    var employedDuringRange = function(p, rangeStartStr, rangeEndStr){
      return p.role==='user' &&
        (!p.effective_date || p.effective_date<=rangeEndStr) &&
        (!p.date_of_termination || p.date_of_termination>=rangeStartStr);
    };

    var headcountAt = function(dateStr){
      return STATE.profiles.filter(function(p){ return employedAt(p, dateStr); }).length;
    };

    // Anyone billed via this client's Initial Invoice already had their
    // headcount-establishment fee collected up front for the year that
    // invoice covered - so they're left out of THAT year's True-Up delta
    // entirely (counted in neither the start nor end figure), otherwise the
    // annual invoice would charge for the same headcount a second time. This
    // only ever affects the one year the Initial Invoice covered; in every
    // later year they're just an ordinary employee like anyone else.
    var initialRosterEmployeeYears = {};
    STATE.entitlementInvoiceItems.forEach(function(item){
      if(item.item_type!=='new_hire' && item.item_type!=='initial_roster') return;
      var inv = STATE.entitlementInvoices.filter(function(i){ return i.id===item.invoice_id && i.status==='issued'; })[0];
      if(!inv || inv.invoice_type!=='initial') return;
      initialRosterEmployeeYears[item.employee_id] = Number(item.effective_date.slice(0,4));
    });
    var isExcludedFromTrueUp = function(p){ return initialRosterEmployeeYears[p.id]===year; };

    var startHeadcount = STATE.profiles.filter(function(p){ return employedAt(p, startStr) && !isExcludedFromTrueUp(p); }).length;
    var endHeadcount = STATE.profiles.filter(function(p){ return employedAt(p, endStr) && !isExcludedFromTrueUp(p); }).length;
    var headcountDelta = endHeadcount - startHeadcount;
    var adjustmentUnits = headcountDelta/2;
    var adjustmentAmount = adjustmentUnits * rate;
    var additionalCharge = Math.max(adjustmentAmount, 0);
    var headcountCredit = Math.max(-adjustmentAmount, 0);

    // What the client was actually billed for an employee's entitlement this
    // year, in priority order: (1) an issued entitlement invoice on record
    // for them this year - use that exact final figure, whatever it ended up
    // being (prorated, full, waived); (2) no record, but they joined *this*
    // year - fall back to the standard proration as a best estimate (this
    // covers anyone added before this feature existed or before an admin
    // got round to invoicing them); (3) anyone else (already on staff before
    // this year, whether still employed or terminated during it) - the full
    // annual allocation, since the client already paid for that full slot.
    // Any promotion invoiced for them this year is added on top either way.
    var billedMap = issuedEntitlementItemsByEmployeeYear();
    var billedAllocationAndTrace = function(p){
      var joinYear = p.effective_date ? Number(p.effective_date.slice(0,4)) : null;
      var billedEntry = billedMap[p.id+'|'+year];
      var allocation, invoiceNumber = null, months = monthsEmployedInYear(p, year);
      if(billedEntry && billedEntry.length){
        allocation = billedEntry.reduce(function(s,e){ return s+(Number(e.item.final_amount)||0); }, 0);
        invoiceNumber = billedEntry.map(function(e){ return e.invoice.invoice_number; }).join(', ');
        months = billedEntry[0].item.months_billed;
      } else if(joinYear===year){
        allocation = proratedAllocationForYear(p, year);
      } else {
        allocation = Number(p.annual_allocation)||0;
      }
      var promoAmount = issuedPromotionAmountForEmployeeYear(p.id, year);
      allocation += promoAmount;
      return {allocation:allocation, invoiceNumber:invoiceNumber, months:months, hadPromotion:promoAmount!==0};
    };

    var employeesInYear = STATE.profiles.filter(function(p){ return employedDuringRange(p, startStr, endStr); });
    var totalEntitlementPool=0, totalApprovedForYear=0;
    var unutilizedByEmployee = employeesInYear.map(function(p){
      var approved = STATE.claims.filter(function(c){
        return c.employee_id===p.id && c.status==='approved' &&
          c.receipt_date && c.receipt_date>=startStr && c.receipt_date<=endStr;
      }).reduce(function(s,c){ return s+sgdAmountOf(c); }, 0);
      var billed = billedAllocationAndTrace(p);
      var unutilized = Math.max(0, billed.allocation-approved);
      totalEntitlementPool += billed.allocation;
      totalApprovedForYear += approved;
      return {name:p.name, allocation:billed.allocation, approved:approved, unutilized:unutilized, invoiceNumber:billed.invoiceNumber};
    }).sort(function(a,b){ return b.unutilized-a.unutilized; });
    var totalUnutilized = unutilizedByEmployee.reduce(function(s,e){ return s+e.unutilized; }, 0);

    var creditNoteAmount = totalUnutilized + headcountCredit;
    var netAmount = additionalCharge - creditNoteAmount;

    // Base Headcount Charge: the invoice also needs to bill for the upcoming
    // year's headcount as at 1 Jan (the year the invoice is dated), on top of
    // the true-up adjustment for the year just closed. This always counts
    // everyone currently on the books, including anyone from an Initial
    // Invoice - that fee only ever covered their onboarding year, not every
    // year going forward.
    var newYearStr = (year+1)+'-01-01';
    var newYearHeadcount = headcountAt(newYearStr);
    var baseHeadcountCharge = newYearHeadcount * rate;
    var totalHeadcountCharge = baseHeadcountCharge + adjustmentAmount;

    // Invoice Payable Amount: what the company is actually billed for the
    // upcoming year's benefit funding, net of the headcount adjustment and
    // any credit note carried in from this year. Subtract totalUnutilized
    // (not the full creditNoteAmount) here - a headcount *decrease* credit
    // is already folded into totalHeadcountCharge via the signed
    // adjustmentAmount, so subtracting creditNoteAmount too would apply
    // that same credit twice.
    var invoicePayableAmount = totalEntitlementPool + totalHeadcountCharge - totalUnutilized;

    var newYearHeadcountList = STATE.profiles.filter(function(p){ return employedAt(p, newYearStr); })
      .map(function(p){ return {name:p.name, allocation:Number(p.annual_allocation)||0}; })
      .sort(function(a,b){ return a.name.localeCompare(b.name); });

    // Supporting lists so the headcount adjustment can be audited: who counted
    // as headcount at the start of the year, and who joined or was terminated
    // during the year (the movements that produced the net change). These
    // mirror the same Initial-Invoice exclusion as the True-Up numbers above,
    // so the lists always add up to the same delta shown there.
    var startHeadcountList = STATE.profiles.filter(function(p){ return employedAt(p, startStr) && !isExcludedFromTrueUp(p); })
      .map(function(p){ return {name:p.name, allocation:Number(p.annual_allocation)||0}; })
      .sort(function(a,b){ return a.name.localeCompare(b.name); });

    var joinedDuringYear = STATE.profiles.filter(function(p){
      return p.role==='user' && p.effective_date && p.effective_date>startStr && p.effective_date<=endStr && !isExcludedFromTrueUp(p);
    });
    var terminatedDuringYear = STATE.profiles.filter(function(p){
      return p.role==='user' && p.date_of_termination && p.date_of_termination>=startStr && p.date_of_termination<=endStr;
    });
    var newJoinersList = joinedDuringYear.map(function(p){
      var billed = billedAllocationAndTrace(p);
      return {name:p.name, allocation:billed.allocation, months:billed.months, date:p.effective_date, invoiceNumber:billed.invoiceNumber};
    }).sort(function(a,b){ return a.date.localeCompare(b.date); });
    // Terminations always show the full annual allocation, never prorated -
    // the client already paid for that employee's full slot for the year
    // (either up front, or via whatever was already billed for them), so
    // this list is purely informational about who left and when.
    var terminationsList = terminatedDuringYear.map(function(p){
      return {name:p.name, allocation:Number(p.annual_allocation)||0, months:monthsEmployedInYear(p, year), date:p.date_of_termination};
    }).sort(function(a,b){ return a.date.localeCompare(b.date); });

    return {
      year:year, rate:rate, startHeadcount:startHeadcount, endHeadcount:endHeadcount,
      headcountDelta:headcountDelta, adjustmentUnits:adjustmentUnits, adjustmentAmount:adjustmentAmount,
      additionalCharge:additionalCharge, headcountCredit:headcountCredit,
      totalEntitlementPool:totalEntitlementPool, totalApprovedForYear:totalApprovedForYear,
      totalUnutilized:totalUnutilized, unutilizedByEmployee:unutilizedByEmployee,
      creditNoteAmount:creditNoteAmount, netAmount:netAmount, invoicePayableAmount:invoicePayableAmount,
      newYearHeadcount:newYearHeadcount, baseHeadcountCharge:baseHeadcountCharge, totalHeadcountCharge:totalHeadcountCharge,
      newYearHeadcountList:newYearHeadcountList,
      startHeadcountList:startHeadcountList, newJoinersList:newJoinersList, terminationsList:terminationsList
    };
  }

  // Applies whatever waiver/override choices are currently set (Preview-time
  // only, never persisted until Issue) to the two headcount-fee lines - the
  // only two lines on the Annual Invoice a waiver makes sense for. Returns a
  // copy of the invoice object with adjustmentAmount/baseHeadcountCharge (and
  // everything downstream of them) recomputed off the final, post-waiver
  // figures, plus the original calculated values for display.
  function applyAnnualWaivers(inv){
    var w = STATE.annualWaivers || {};
    var adjWaiver = w.headcountAdjustment || {status:'normal'};
    var baseWaiver = w.baseHeadcountCharge || {status:'normal'};
    var finalAdjustment = adjWaiver.status==='waived' ? 0 : (adjWaiver.status==='custom' && adjWaiver.amount!=null ? Number(adjWaiver.amount) : inv.adjustmentAmount);
    var finalBase = baseWaiver.status==='waived' ? 0 : (baseWaiver.status==='custom' && baseWaiver.amount!=null ? Number(baseWaiver.amount) : inv.baseHeadcountCharge);
    var finalAdditionalCharge = Math.max(finalAdjustment, 0);
    var finalHeadcountCredit = Math.max(-finalAdjustment, 0);
    var finalTotalHeadcountCharge = finalBase + finalAdjustment;
    var finalCreditNote = inv.totalUnutilized + finalHeadcountCredit;
    var finalNetAmount = finalAdditionalCharge - finalCreditNote;
    var finalInvoicePayable = inv.totalEntitlementPool + finalTotalHeadcountCharge - inv.totalUnutilized;
    var out = {};
    for(var k in inv){ out[k]=inv[k]; }
    out.calculatedAdjustmentAmount = inv.adjustmentAmount;
    out.calculatedBaseHeadcountCharge = inv.baseHeadcountCharge;
    out.adjustmentAmount = finalAdjustment;
    out.baseHeadcountCharge = finalBase;
    out.additionalCharge = finalAdditionalCharge;
    out.headcountCredit = finalHeadcountCredit;
    out.totalHeadcountCharge = finalTotalHeadcountCharge;
    out.creditNoteAmount = finalCreditNote;
    out.netAmount = finalNetAmount;
    out.invoicePayableAmount = finalInvoicePayable;
    out.adjustmentWaiver = adjWaiver;
    out.baseWaiver = baseWaiver;
    return out;
  }

  // Issues the Annual Invoice for the currently-selected year: draws the
  // next number off the shared sequence, freezes the full post-waiver
  // computation into snapshot_json so a later redownload always reproduces
  // exactly what was issued, and downloads the PDF immediately. The unique
  // index on annual_invoices(year) where status='issued' is the real guard
  // against double-issuing a year - this check just gives a friendlier
  // message up front.
  function issueAnnualInvoice(){
    var year = getSelectedInvoiceYear();
    var already = STATE.annualInvoices.filter(function(a){ return a.year===year && a.status==='issued'; })[0];
    if(already){ showToast('An Annual Invoice for '+year+' has already been issued ('+already.invoice_number+'). Void it first to reissue.', 'error'); return Promise.resolve(); }
    // Auto-link Void + Reissue: if this year has a voided Annual Invoice
    // with no successor yet, this new one is presumed to be its correction.
    var precedingVoided = findUnsupersededVoid(STATE.annualInvoices, function(a){ return a.year===year; });
    var inv = applyAnnualWaivers(computeAnnualInvoice(year));
    return nextInvoiceNumber().then(function(invoiceNumber){
      var row = {
        invoice_number: invoiceNumber, year: year, status:'issued', issued_by: STATE.session.user.id,
        supersedes_invoice_id: precedingVoided ? precedingVoided.id : null,
        rate_per_head: inv.rate,
        headcount_adjustment_amount: inv.adjustmentAmount,
        headcount_adjustment_waived: !!(inv.adjustmentWaiver && inv.adjustmentWaiver.status==='waived'),
        headcount_adjustment_waived_reason: (inv.adjustmentWaiver && inv.adjustmentWaiver.status!=='normal') ? inv.adjustmentWaiver.reason : null,
        headcount_adjustment_override: (inv.adjustmentWaiver && inv.adjustmentWaiver.status==='custom') ? inv.adjustmentWaiver.amount : null,
        base_headcount_charge: inv.baseHeadcountCharge,
        base_headcount_waived: !!(inv.baseWaiver && inv.baseWaiver.status==='waived'),
        base_headcount_waived_reason: (inv.baseWaiver && inv.baseWaiver.status!=='normal') ? inv.baseWaiver.reason : null,
        base_headcount_override: (inv.baseWaiver && inv.baseWaiver.status==='custom') ? inv.baseWaiver.amount : null,
        total_headcount_charge: inv.totalHeadcountCharge,
        total_entitlement_pool: inv.totalEntitlementPool,
        total_unutilized: inv.totalUnutilized,
        credit_note_amount: inv.creditNoteAmount,
        net_amount: inv.netAmount,
        invoice_payable_amount: inv.invoicePayableAmount,
        snapshot_json: inv
      };
      return supabase.from('annual_invoices').insert([row]).select().then(function(res){
        if(res.error || !res.data || !res.data[0]){ showToast('Could not issue Annual Invoice: '+(res.error&&res.error.message), 'error'); throw res.error; }
        var savedRow = res.data[0];
        STATE.annualWaivers = {};
        showToast('Annual Invoice '+invoiceNumber+' issued.'+(precedingVoided?(' Supersedes '+precedingVoided.invoice_number+'.'):''), 'success');
        exportInvoicePDF({inv: savedRow.snapshot_json, year: year, invoiceNumber: invoiceNumber, invoiceDate: '2 Jan '+(year+1), preview:false, supersedesNumber: precedingVoided?precedingVoided.invoice_number:null});
        return loadAppData();
      });
    }).then(function(){ render(); });
  }

  function voidAnnualInvoice(id, reason){
    if(!reason || !reason.trim()){ showToast('A reason is required to void an invoice.', 'error'); return Promise.resolve(); }
    return supabase.from('annual_invoices').update({status:'voided', voided_reason:reason.trim(), voided_at:new Date().toISOString()}).eq('id', id).then(function(res){
      if(res.error){ showToast('Could not void invoice: '+res.error.message, 'error'); return; }
      showToast('Invoice voided.', 'success');
      STATE.voidingInvoice = null; STATE.voidReasonDraft='';
      return loadAppData();
    }).then(function(){ render(); });
  }

  function uniqueYearsFromClaims(claims, currentYear){
    var years = {}; years[currentYear]=true;
    claims.forEach(function(c){ if(c.receipt_date){ years[new Date(c.receipt_date+'T00:00:00').getFullYear()]=true; } });
    return Object.keys(years).map(Number).sort(function(a,b){ return b-a; });
  }

  var REPORT_MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];

  function buildReportYearOptions(claims){
    var now = new Date();
    var currentYear = now.getFullYear();
    var options = [{value:String(currentYear), label:String(currentYear)},
      {value:'ytd', label:'Year to Date '+currentYear+' ('+REPORT_MONTH_NAMES[0].slice(0,3)+'-'+REPORT_MONTH_NAMES[now.getMonth()].slice(0,3)+')'}];
    uniqueYearsFromClaims(claims, currentYear).filter(function(yr){ return yr!==currentYear; }).forEach(function(yr){
      options.push({value:String(yr), label:String(yr)});
    });
    return options;
  }

  function resolveReportPeriod(yearValue, monthValue){
    var now = new Date();
    if(yearValue==='ytd'){
      return {
        startDate: new Date(now.getFullYear(),0,1,0,0,0),
        endDate: now,
        label: 'Year to Date '+now.getFullYear()+' ('+REPORT_MONTH_NAMES[0].slice(0,3)+'-'+REPORT_MONTH_NAMES[now.getMonth()].slice(0,3)+')',
        fileSuffix: now.getFullYear()+'-YTD'
      };
    }
    var yr = parseInt(yearValue,10); if(isNaN(yr)) yr = now.getFullYear();
    var mo = parseInt(monthValue,10); if(isNaN(mo)) mo = now.getMonth();
    return {
      startDate: new Date(yr,mo,1,0,0,0),
      endDate: new Date(yr,mo+1,0,23,59,59),
      label: REPORT_MONTH_NAMES[mo]+' '+yr,
      fileSuffix: yr+'-'+String(mo+1).padStart(2,'0')
    };
  }

  /* =========================================================
     AUTH + DATA LOADING
  ========================================================== */
  function loadProfileAndData(){
    return supabase.from('profiles').select('*').eq('id', STATE.session.user.id).single().then(function(res){
      if(res.error || !res.data){ throw new Error('Could not load your account. If you just signed up, make sure your admin invited this exact email.'); }
      // Two independent ways an account can be locked out: an admin
      // explicitly flipped Deactivate, or their Date of Termination has
      // actually arrived. The termination check is deliberately date-based
      // rather than tied to the `active` flag, so a *future* termination
      // date (e.g. serving out a notice period) doesn't cut anyone off
      // early - they keep normal access right up until that date, then are
      // locked out automatically from the next login attempt onward with no
      // separate Deactivate step required.
      var isTerminated = res.data.date_of_termination && res.data.date_of_termination<=todayStr();
      if(!res.data.active || isTerminated){
        return supabase.auth.signOut().then(function(){
          STATE.authError = isTerminated
            ? 'This account\'s employment has ended. Contact your administrator.'
            : 'This account has been deactivated. Contact your administrator.';
          throw new Error('deactivated');
        });
      }
      STATE.profile = res.data;
      return loadAppData();
    });
  }

  function loadAppData(){
    var isAdmin = STATE.profile && STATE.profile.role === 'admin';
    var calls = [
      supabase.from('benefits').select('*').order('name'),
      supabase.from('reject_reasons').select('*').order('reason'),
      supabase.from('claims').select('*').order('submitted_at', {ascending:false}),
      supabase.from('notifications').select('*').order('created_at', {ascending:false}),
      supabase.from('family_members').select('*').order('name')
    ];
    if(isAdmin){
      calls.push(supabase.from('profiles').select('*').order('name'));
      calls.push(supabase.from('invites').select('*').order('created_at', {ascending:false}));
      calls.push(supabase.from('app_settings').select('*'));
      calls.push(supabase.from('allocation_changes').select('*').order('created_at', {ascending:false}));
      calls.push(supabase.from('entitlement_invoices').select('*').order('issued_at', {ascending:false}));
      calls.push(supabase.from('entitlement_invoice_items').select('*'));
      calls.push(supabase.from('annual_invoices').select('*').order('issued_at', {ascending:false}));
    }
    return Promise.all(calls).then(function(results){
      STATE.benefits = (results[0].data||[]).map(function(b){ return b.name; });
      STATE.rejectReasons = (results[1].data||[]).map(function(r){ return r.reason; });
      STATE.claims = results[2].data || [];
      STATE.notifications = results[3].data || [];
      STATE.familyMembers = results[4].data || [];
      if(isAdmin){
        STATE.profiles = results[5].data || [];
        STATE.invites = results[6].data || [];
        STATE.appSettings = {};
        (results[7].data||[]).forEach(function(s){ STATE.appSettings[s.key] = s.value; });
        STATE.allocationChanges = results[8].data || [];
        STATE.entitlementInvoices = results[9].data || [];
        STATE.entitlementInvoiceItems = results[10].data || [];
        STATE.annualInvoices = results[11].data || [];
      } else {
        STATE.invites = [];
        // A regular employee's own profile row (allocation, Prorate
        // setting, etc.) was only ever fetched once at login and then
        // reused here from memory - so a standing setting an admin changed
        // for them (e.g. the Prorate toggle) never showed up until they
        // logged out and back in, even though this function was already
        // being re-run (after submitting a claim, or via the realtime
        // subscription below). Re-fetch it fresh every time so those paths
        // actually pick up the change.
        return supabase.from('profiles').select('*').eq('id', STATE.session.user.id).single().then(function(res){
          if(!res.error && res.data){ STATE.profile = res.data; }
          STATE.profiles = STATE.profile ? [STATE.profile] : [];
        });
      }
    });
  }

  function subscribeRealtime(){
    if(STATE._realtimeSubscribed || !supabase) return;
    STATE._realtimeSubscribed = true;
    ['claims','benefits','notifications','profiles','app_settings'].forEach(function(table){
      supabase.channel(table+'-rt')
        .on('postgres_changes', {event:'*', schema:'public', table:table}, handleRealtimeChange)
        .subscribe();
    });
  }

  var realtimeDebounceTimer = null;
  function handleRealtimeChange(){
    clearTimeout(realtimeDebounceTimer);
    realtimeDebounceTimer = setTimeout(function(){
      if(!STATE.profile) return;
      loadAppData().then(function(){
        var activeEl = document.activeElement;
        var isTyping = activeEl && ['INPUT','TEXTAREA'].indexOf(activeEl.tagName)!==-1;
        if(!isTyping){
          var preserved = STATE.activeTab==='claim' ? captureClaimFormValues() : null;
          render();
          if(preserved){ restoreClaimFormValues(preserved); }
        }
      }).catch(function(err){ console.error('realtime refresh failed', err); });
    }, 400);
  }

  function init(){
    if(!supabase){ STATE.loading = false; render(); return; }
    // Register this before getSession() so the client's own detection of a
    // password-recovery link in the URL (which happens as soon as the page
    // loads) is never missed -- it fires PASSWORD_RECOVERY here rather than
    // just quietly logging the person in with their old password still active.
    supabase.auth.onAuthStateChange(function(event, session){
      if(event === 'SIGNED_OUT'){
        STATE.session = null; STATE.profile = null; STATE.activeTab = null;
        render();
      }
      if(event === 'PASSWORD_RECOVERY'){
        STATE.passwordRecovery = true;
        STATE.loading = false;
        render();
      }
    });
    STATE.loading = true; render();
    supabase.auth.getSession().then(function(res){
      STATE.session = res.data.session;
      return STATE.session ? loadProfileAndData() : null;
    }).then(function(){
      STATE.loading = false;
      if(STATE.profile){ STATE.activeTab = STATE.profile.role==='admin' ? 'approvals' : 'dashboard'; }
      render();
      if(STATE.profile){ subscribeRealtime(); }
    }).catch(function(err){
      console.error(err);
      STATE.session = null; STATE.profile = null; STATE.loading = false;
      render();
    });
  }

  /* =========================================================
     RENDER - TOP LEVEL
  ========================================================== */
  function render(){
    var app = document.getElementById('app');
    if(!supabase){ app.innerHTML = renderSetupNeeded(); return; }
    if(STATE.loading){ app.innerHTML = renderLoading() + renderBrandFooter(); return; }
    if(STATE.passwordRecovery){ app.innerHTML = renderResetPassword() + renderBrandFooter(); return; }
    if(!STATE.session || !STATE.profile){ app.innerHTML = renderAuthScreen() + renderBrandFooter(); return; }
    app.innerHTML = (STATE.profile.role==='admin' ? renderAdminShell() : renderUserShell()) + renderBrandFooter();
    if(STATE.modal){
      var host = document.createElement('div');
      host.innerHTML = renderModal();
      if(host.firstElementChild) app.appendChild(host.firstElementChild);
    }
    if(STATE.toast){
      var thost = document.createElement('div');
      thost.innerHTML = renderToast();
      if(thost.firstElementChild) app.appendChild(thost.firstElementChild);
    }
  }

