  // Entitlement invoice PDF (New Hire / Promotion / Initial Roster). Per
  // Tin's feedback, this is issued BY Cresco but reads softer than the
  // Annual Invoice - the Cresco red is used as a thin accent (a rule under
  // the header, a small tick before each section heading, and the table
  // header outline) rather than a full solid banner.
  //
  // opts is either {invoiceRow, items} for an already-issued invoice
  // (Issue action or a re-download from history), or {preview:true,
  // previewData} for a live Preview - previewData is whatever
  // computeEntitlementInvoicePreview() returned, nothing saved or numbered.
  function exportEntitlementInvoicePDF(opts){
    if(typeof window.jspdf==='undefined' || !window.jspdf.jsPDF){ showToast('PDF export library did not load (needs an internet connection).', 'error'); return; }
    try{
      var isPreview = !!opts.preview;
      var previewData = opts.previewData;
      var invoiceRow = opts.invoiceRow;
      var invoiceType = isPreview ? previewData.invoiceType : invoiceRow.invoice_type;
      var isInitial = invoiceType==='initial';
      var invoiceNumber = isPreview ? 'DRAFT - NOT YET ISSUED' : invoiceRow.invoice_number;
      var invoiceDate = isPreview ? fmtDate(new Date().toISOString().slice(0,10)) : fmtDate((invoiceRow.issued_at||'').slice(0,10));

      var lines = isPreview
        ? previewData.lines.map(function(l){
            return {
              employeeName: l.item.employeeName, itemType: l.item.type, effectiveDate: l.item.effectiveDate,
              monthsBilled: l.item.months, prorated: l.selection.prorate,
              calculatedAmount: l.calculatedAmount, finalAmount: l.finalAmount,
              waiveStatus: l.selection.waiveStatus, waiveReason: l.selection.waiveReason
            };
          })
        : (opts.items||[]).map(function(it){
            return {
              employeeName: it.employee_name, itemType: it.item_type, effectiveDate: it.effective_date,
              monthsBilled: it.months_billed, prorated: it.prorated,
              calculatedAmount: it.calculated_amount, finalAmount: it.final_amount,
              waiveStatus: it.waived ? 'waived' : (it.override_amount!=null ? 'custom' : 'normal'), waiveReason: it.waived_reason
            };
          });
      var entitlementTotal = isPreview ? previewData.entitlementTotal : (Number(invoiceRow.entitlement_total)||0);
      var perPaxRate = isPreview ? (isInitial?previewData.rate:null) : invoiceRow.per_pax_rate;
      var perPaxTotal = isPreview ? previewData.perPaxTotal : (Number(invoiceRow.per_pax_total)||0);
      var headcountForPax = isPreview ? previewData.headcountForPax : lines.filter(function(l){ return l.itemType!=='promotion'; }).length;
      var totalAmount = isPreview ? previewData.totalAmount : (Number(invoiceRow.total_amount)||0);

      var doc = new window.jspdf.jsPDF({unit:'mm', format:'a4'});
      var pageWidth = doc.internal.pageSize.getWidth();
      var margin = 15;
      var accent = CRESCO_COLOR_RGB;

      var logoW = 30, logoH = logoW*(90/285);
      doc.addImage(CRESCO_LOGO_DATA_URI, 'PNG', margin, 10, logoW, logoH);
      doc.setTextColor(50,50,50);
      doc.setFontSize(15);
      doc.text(isInitial ? 'Initial Roster Invoice' : 'New Hire / Promotion Invoice', pageWidth-margin, 16, {align:'right'});
      doc.setFontSize(9);
      doc.setTextColor(120,120,120);
      doc.text('Entitlement Billing - Flex Benefits Portal by Cresco Insurance Agency Pte Ltd', pageWidth-margin, 22, {align:'right'});
      doc.setDrawColor(accent[0],accent[1],accent[2]);
      doc.setLineWidth(0.8);
      doc.line(margin, 27, pageWidth-margin, 27);

      doc.setTextColor(40,40,40);
      doc.setFontSize(9);
      var iy = 35;
      doc.text('Invoice Date: '+invoiceDate, margin, iy);
      if(isPreview){ doc.setTextColor(200,120,0); doc.text('Invoice No: '+invoiceNumber, margin, iy+6); doc.setTextColor(40,40,40); }
      else { doc.text('Invoice No: '+invoiceNumber, margin, iy+6); }
      var byLineY = iy+12;
      doc.text('Bill To: '+getClientCompanyName(), margin, byLineY);
      if(opts.supersedesNumber){ byLineY += 6; doc.setTextColor(120,120,120); doc.text('Supersedes voided invoice: '+opts.supersedesNumber, margin, byLineY); doc.setTextColor(40,40,40); }

      var sectionHeading = function(text, y){
        doc.setFillColor(accent[0],accent[1],accent[2]);
        doc.rect(margin, y-4, 2.2, 4.6, 'F');
        doc.setFontSize(12); doc.setTextColor(40,40,40);
        doc.text(text, margin+5, y);
      };

      var cy = byLineY+12;
      sectionHeading((isInitial?'Initial Roster - ':'')+'Entitlement Charges', cy);
      cy += 5;
      var rows = lines.map(function(l){
        var typeLabel = l.itemType==='promotion' ? 'Promotion' : (isInitial ? 'Initial Roster' : 'New Hire');
        var amountText = (l.waiveStatus && l.waiveStatus!=='normal')
          ? ('Calc. '+fmtMoney(l.calculatedAmount)+' -> '+(l.waiveStatus==='waived'?'Waived off':fmtMoney(l.finalAmount))+(l.waiveReason?' ('+l.waiveReason+')':''))
          : fmtMoney(l.finalAmount);
        return [l.employeeName, typeLabel, fmtDate(l.effectiveDate), l.prorated?(l.monthsBilled+' of 12'):'Full year', amountText];
      });
      doc.autoTable({
        startY: cy, margin:{left:margin, right:margin},
        head:[['Employee','Type','Effective Date','Billed As','Amount (SGD)']], body: rows.length?rows:[['No line items on this invoice.','','','','']],
        theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:accent, lineWidth:0.3},
        styles:{fontSize:9, lineColor:[225,225,225]}
      });
      cy = doc.lastAutoTable.finalY + 12;

      if(isInitial){
        sectionHeading('Headcount Establishment Charge', cy);
        cy += 5;
        doc.autoTable({
          startY: cy, margin:{left:margin, right:margin},
          body: [
            ['Employees Established', String(headcountForPax)],
            ['Rate per Head (one-time, flat - not prorated)', fmtMoney(perPaxRate)],
            ['Per-Pax Establishment Total', fmtMoney(perPaxTotal)]
          ],
          theme:'plain', styles:{fontSize:10, cellPadding:1.5},
          columnStyles:{0:{fontStyle:'bold', cellWidth:110}}
        });
        cy = doc.lastAutoTable.finalY + 12;
      }

      sectionHeading('Invoice Summary', cy);
      cy += 5;
      var summaryBody = [['Entitlement Total', fmtMoney(entitlementTotal)]];
      if(isInitial) summaryBody.push(['Per-Pax Establishment Total', fmtMoney(perPaxTotal)]);
      summaryBody.push(['Total Amount Due', fmtMoney(totalAmount)]);
      doc.autoTable({
        startY: cy, margin:{left:margin, right:margin},
        body: summaryBody,
        theme:'grid', headStyles:{fillColor:accent},
        styles:{fontSize:10, cellPadding:2},
        columnStyles:{0:{fontStyle:'bold', cellWidth:110}},
        didParseCell: function(data){
          if(data.row.index===summaryBody.length-1){ data.cell.styles.fontStyle='bold'; data.cell.styles.fillColor=[250,240,241]; }
        }
      });
      cy = doc.lastAutoTable.finalY + 10;
      doc.setFontSize(8); doc.setTextColor(120,120,120);
      var footNote = doc.splitTextToSize('This invoice bills entitlement dollars only - any headcount adjustment or base headcount charge for this client is billed separately on the Annual Invoice.'+(isPreview?' This is a draft preview - nothing has been saved or numbered yet.':''), pageWidth-margin*2);
      doc.text(footNote, margin, cy);

      var fileTag = isPreview ? 'DRAFT' : String(invoiceNumber).replace(/[^A-Za-z0-9-]/g,'');
      doc.save('entitlement-invoice-'+fileTag+'.pdf');
    }catch(err){
      console.error(err);
      showToast('Could not generate the invoice PDF. Check the console for details.', 'error');
    }
  }

  /* =========================================================
     ACTION HANDLERS - AUTH
  ========================================================== */
  function doLogin(form){
    var email = form.email.value.trim();
    var password = form.password.value;
    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Logging in...';
    return withNetworkRetry(function(){ return supabase.auth.signInWithPassword({email:email, password:password}); }).then(function(res){
      if(res.error){ STATE.authError = res.error.message; render(); return; }
      STATE.authError=''; STATE.authInfo=''; STATE.session = res.data.session;
      STATE.loading = true; render();
      return loadProfileAndData().then(function(){
        STATE.loading=false;
        STATE.activeTab = STATE.profile.role==='admin' ? 'approvals' : 'dashboard';
        render();
        subscribeRealtime();
      }).catch(function(err){
        STATE.loading=false; STATE.session=null; STATE.profile=null;
        if(err.message!=='deactivated'){ STATE.authError = err.message; }
        render();
      });
    }).catch(function(err){
      STATE.authError = (err && err.message) || 'Login failed - please try again.';
      render();
    });
  }

  function doSignup(form){
    var email = form.email.value.trim();
    var password = form.password.value;
    var confirmPassword = form.confirmPassword.value;
    if(password !== confirmPassword){ STATE.authError='Passwords do not match.'; render(); return Promise.resolve(); }
    if(password.length < 6){ STATE.authError='Password must be at least 6 characters.'; render(); return Promise.resolve(); }
    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Creating account...';
    var redirectTo = window.location.origin + window.location.pathname;
    return withNetworkRetry(function(){ return supabase.auth.signUp({email:email, password:password, options:{emailRedirectTo:redirectTo}}); }).then(function(res){
      if(res.error){
        var msg = res.error.message || '';
        if(/already registered|already exists|already been registered/i.test(msg)){
          STATE.authError = 'This email is already registered. Please log in instead.';
          showToast('This email is already registered - try logging in instead.', 'error');
        } else {
          STATE.authError = msg;
          render();
        }
        return;
      }
      var alreadyRegistered = res.data && res.data.user && Array.isArray(res.data.user.identities) && res.data.user.identities.length===0;
      if(alreadyRegistered){
        STATE.authError = 'This email is already registered. Please log in instead.';
        showToast('This email is already registered - try logging in instead.', 'error');
        return;
      }
      if(res.data.session){
        STATE.session = res.data.session;
        STATE.loading = true; render();
        return loadProfileAndData().then(function(){
          STATE.loading=false;
          STATE.activeTab = STATE.profile.role==='admin' ? 'approvals' : 'dashboard';
          render();
          subscribeRealtime();
        });
      }
      STATE.authView='login'; STATE.authError='';
      STATE.authInfo='Account created! Check your email to confirm, then log in.';
      render();
    }).catch(function(err){
      STATE.authError = (err && err.message) || 'Could not create account - please try again.';
      render();
    });
  }

  function doForgotPassword(form){
    var email = form.email.value.trim();
    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Sending...';
    STATE.authError = '';
    var redirectTo = window.location.origin + window.location.pathname;
    return withNetworkRetry(function(){ return withTimeout(supabase.auth.resetPasswordForEmail(email, {redirectTo:redirectTo}), 8000, 'Password reset request'); }).then(function(res){
      if(res.error){ STATE.authError = res.error.message; render(); return; }
      STATE.authView = 'forgot-sent'; STATE.authError = '';
      render();
    }).catch(function(err){
      STATE.authError = (err && err.message) || 'Could not send reset email - please try again.';
      render();
    });
  }

  function doResetPassword(form){
    var password = form.password.value;
    var confirmPassword = form.confirmPassword.value;
    if(password !== confirmPassword){ STATE.authError = 'Passwords do not match.'; render(); return Promise.resolve(); }
    if(password.length < 6){ STATE.authError = 'Password must be at least 6 characters.'; render(); return Promise.resolve(); }
    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Saving...';
    STATE.authError = '';
    return withNetworkRetry(function(){ return supabase.auth.updateUser({password:password}); }).then(function(res){
      if(res.error){ STATE.authError = res.error.message; render(); return; }
      // Drop the temporary recovery session and send them to the ordinary
      // login screen to sign in fresh with the new password -- same pattern
      // as new-user signup, rather than silently carrying them into the app.
      STATE.passwordRecovery = false;
      STATE.authView = 'login'; STATE.authError = '';
      STATE.authInfo = 'Password updated - please log in with your new password.';
      render();
      return supabase.auth.signOut();
    }).catch(function(err){
      STATE.authError = (err && err.message) || 'Could not update password - please try again.';
      render();
    });
  }

  /* =========================================================
     ACTION HANDLERS - CLAIMS
  ========================================================== */
  function openReceiptModal(id){
    var claim = STATE.claims.filter(function(c){ return c.id===id; })[0];
    if(!claim || !claim.receipt_path) return;
    supabase.storage.from('receipts').createSignedUrl(claim.receipt_path, 120).then(function(res){
      if(res.error){ showToast('Could not load receipt.', 'error'); return; }
      STATE.modal = {type:'image', src:res.data.signedUrl, title:claim.category+' - '+fmtDate(claim.receipt_date), isImage:isImageName(claim.receipt_name), name:claim.receipt_name};
      render();
    });
  }

  // Makes a Storage object name safe and readable: letters/numbers/dashes
  // only, no run of repeated dashes, nothing leading/trailing.
  function sanitizeForFilename(s){
    return String(s||'').trim().replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-+|-+$/g,'') || 'file';
  }

  function uploadReceipt(file, category, receiptDate){
    var ext = (file.name.split('.').pop()||'bin').toLowerCase();
    // The FOLDER stays keyed by the employee's auth id - that's what the
    // receipts_* Storage policies check to enforce "only this employee or
    // an admin can see this file", and ids are stable/unique in a way a
    // name never is (two employees can share a name, and a name can be
    // corrected later). The FILENAME, though, is just for humans browsing
    // Storage directly during an audit - so it leads with the employee's
    // name, then the receipt date and category, so a folder's contents are
    // self-explanatory without having to open the app or match the file to
    // a claims row first.
    var namePart = sanitizeForFilename(STATE.profile && STATE.profile.name);
    var datePart = sanitizeForFilename(receiptDate || new Date().toISOString().slice(0,10));
    var catPart = sanitizeForFilename(category);
    var uniquePart = Date.now() + '-' + Math.random().toString(36).slice(2,8);
    var filename = [namePart, datePart, catPart, uniquePart].filter(Boolean).join('_') + '.' + ext;
    var path = STATE.session.user.id + '/' + filename;
    return withNetworkRetry(function(){ return supabase.storage.from('receipts').upload(path, file); }).then(function(res){
      if(res.error) throw res.error;
      return {path:path, name:file.name};
    });
  }

  function submitClaim(form){
    var category = form.category.value;
    var vendor = form.vendor.value.trim();
    var currency = form.currency.value || 'SGD';
    var amount = parseFloat(form.amount.value);
    var receiptDate = form.receiptDate.value;
    var file = form.receipt.files[0];
    var familyMemberIdField = form.querySelector('[name="familyMemberId"]');
    var familyMemberId = familyMemberIdField ? (familyMemberIdField.value || null) : null;
    if(!category || !vendor || !amount || amount<=0 || !receiptDate || !file){ showToast('Please complete all fields.', 'error'); return Promise.resolve(); }
    if(file.size > 4*1024*1024){ showToast('File too large - please upload a file under 4MB.', 'error'); return Promise.resolve(); }

    var currentYear = new Date().getFullYear();
    var receiptYear = new Date(receiptDate+'T00:00:00').getFullYear();
    if(receiptYear !== currentYear){
      STATE.claimFormError = 'This receipt is dated '+fmtDate(receiptDate)+', which is not from '+currentYear+'. Only '+currentYear+' receipts can be claimed - your benefits reset every 1 January.';
      render();
      return Promise.resolve();
    }

    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Checking exchange rate...';

    return getExchangeRateToSGD(currency).then(function(rate){
      var amountSgd = Math.round(amount*rate*100)/100;
      var wallet = computeWallet(STATE.profile.id);
      if(amountSgd > wallet.available){
        STATE.claimFormError = 'This comes to '+fmtMoney(amountSgd)+' SGD, which is more than your available balance of '+fmtMoney(wallet.available)+'.';
        render();
        return null;
      }
      STATE.claimFormError = null;
      btn.textContent = 'Uploading...';
      return uploadReceipt(file, category, receiptDate).then(function(receipt){
        return withNetworkRetry(function(){
          return supabase.from('claims').insert({
            employee_id: STATE.session.user.id, category:category, vendor:vendor,
            amount:amount, currency:currency, amount_sgd:amountSgd, exchange_rate:rate,
            receipt_date:receiptDate, receipt_path:receipt.path, receipt_name:receipt.name, status:'pending',
            family_member_id: familyMemberId
          });
        });
      });
    }).then(function(res){
      if(res===null) return;
      if(res.error) throw res.error;
      showToast('Claim submitted successfully and is pending review.', 'success');
      STATE.activeTab = 'history';
      return loadAppData();
    }).then(function(){ render(); }).catch(function(err){
      console.error(err);
      showToast('Something went wrong: '+(err.message||err), 'error');
      render();
    });
  }

  function approveClaim(id){
    return supabase.from('claims').update({status:'approved', decided_at:new Date().toISOString()}).eq('id', id).then(function(res){
      if(res.error){ showToast('Could not approve claim: '+res.error.message, 'error'); return; }
      showToast('Claim approved.', 'success');
      return loadAppData();
    }).then(function(){ render(); });
  }

  function confirmReject(id){
    var reasonSel = document.querySelector('[data-field="reject-reason-'+id+'"]');
    var noteInput = document.querySelector('[data-field="reject-note-'+id+'"]');
    var otherInput = document.querySelector('[data-field="reject-other-'+id+'"]');
    var reason = reasonSel ? reasonSel.value : '';
    if(!reason){ showToast('Please select a rejection reason.', 'error'); return Promise.resolve(); }
    if(reason==='Others'){
      var customReason = otherInput ? otherInput.value.trim() : '';
      if(!customReason){ showToast('Please specify a reason.', 'error'); return Promise.resolve(); }
      reason = customReason;
    }
    var note = noteInput ? noteInput.value.trim() : '';
    return supabase.from('claims').update({status:'rejected', reject_reason:reason, admin_note:note, decided_at:new Date().toISOString()}).eq('id', id).then(function(res){
      if(res.error){ showToast('Could not reject claim: '+res.error.message, 'error'); return; }
      STATE.rejectingClaimId = null;
      showToast('Claim rejected and employee notified.', 'success');
      return loadAppData();
    }).then(function(){ render(); });
  }

  function markNotificationRead(id){
    return supabase.from('notifications').update({read:true}).eq('id', id).then(function(res){
      if(res.error) return;
      return loadAppData();
    }).then(function(){ render(); });
  }

  function confirmEditClaim(id){
    var claim = STATE.claims.filter(function(c){ return c.id===id; })[0];
    if(!claim) return Promise.resolve();
    if(claim.employee_id !== STATE.session.user.id){ showToast('You can only edit your own claims.', 'error'); return Promise.resolve(); }
    if(claim.status==='approved'){ showToast('Approved claims cannot be edited.', 'error'); return Promise.resolve(); }

    var catSel = document.getElementById('edit-category-'+id);
    var vendorInput = document.getElementById('edit-vendor-'+id);
    var currencySel = document.getElementById('edit-currency-'+id);
    var amtInput = document.getElementById('edit-amount-'+id);
    var dateInput = document.getElementById('edit-date-'+id);
    var fileInput = document.getElementById('edit-receipt-'+id);
    var familySel = document.getElementById('edit-family-'+id);
    var category = catSel ? catSel.value : claim.category;
    var vendor = vendorInput ? vendorInput.value.trim() : claim.vendor;
    var currency = currencySel ? currencySel.value : (claim.currency||'SGD');
    var amount = amtInput ? parseFloat(amtInput.value) : claim.amount;
    var receiptDate = dateInput ? dateInput.value : claim.receipt_date;
    var familyMemberId = familySel ? (familySel.value || null) : claim.family_member_id;
    if(!category || !vendor || !amount || amount<=0 || !receiptDate){ showToast('Please complete all fields.', 'error'); return Promise.resolve(); }

    var currentYear = new Date().getFullYear();
    var receiptYear = new Date(receiptDate+'T00:00:00').getFullYear();
    if(receiptYear !== currentYear){
      STATE.claimFormError = 'This receipt is dated '+fmtDate(receiptDate)+', which is not from '+currentYear+'. Only '+currentYear+' receipts can be claimed - your benefits reset every 1 January.';
      render();
      return Promise.resolve();
    }

    var file = fileInput && fileInput.files && fileInput.files[0];
    var wasRejected = claim.status === 'rejected';

    return getExchangeRateToSGD(currency).then(function(rate){
      var amountSgd = Math.round(amount*rate*100)/100;
      var wallet = computeWallet(STATE.profile.id);
      var availableForThisEdit = claim.status==='pending' ? wallet.available + sgdAmountOf(claim) : wallet.available;
      if(amountSgd > availableForThisEdit){
        STATE.claimFormError = 'This comes to '+fmtMoney(amountSgd)+' SGD, which is more than your available balance of '+fmtMoney(availableForThisEdit)+'.';
        render();
        return null;
      }
      STATE.claimFormError = null;

      var updates = {category:category, vendor:vendor, currency:currency, amount:amount, amount_sgd:amountSgd, exchange_rate:rate, receipt_date:receiptDate, last_edited_at:new Date().toISOString(), family_member_id:familyMemberId};
      if(wasRejected){ updates.status='pending'; updates.reject_reason=null; updates.admin_note=null; updates.decided_at=null; }

      function applyUpdate(){
        return supabase.from('claims').update(updates).eq('id', id).then(function(res){
          if(res.error){ showToast('Could not save changes: '+res.error.message, 'error'); return; }
          STATE.editingClaimId = null;
          showToast(wasRejected ? 'Claim updated and resubmitted for review.' : 'Claim updated.', 'success');
          return loadAppData();
        }).then(function(){ render(); });
      }

      if(file){
        if(file.size > 4*1024*1024){ showToast('File too large - please upload a file under 4MB.', 'error'); return null; }
        return uploadReceipt(file, category, receiptDate).then(function(receipt){
          updates.receipt_path = receipt.path; updates.receipt_name = receipt.name;
          return applyUpdate();
        }).catch(function(err){ showToast('Upload failed: '+(err.message||err), 'error'); });
      }
      return applyUpdate();
    }).catch(function(err){
      console.error(err);
      showToast('Could not fetch the exchange rate: '+(err.message||err), 'error');
    });
  }

  function deleteClaimConfirmed(id){
    var claim = STATE.claims.filter(function(c){ return c.id===id; })[0];
    STATE.confirmDeleteClaimId = null;
    if(!claim){ render(); return Promise.resolve(); }
    if(claim.employee_id !== STATE.session.user.id){ showToast('You can only delete your own claims.', 'error'); render(); return Promise.resolve(); }
    if(claim.status==='approved'){ showToast('Approved claims cannot be deleted.', 'error'); render(); return Promise.resolve(); }
    return supabase.from('claims').delete().eq('id', id).then(function(res){
      if(res.error){ showToast('Could not delete claim: '+res.error.message, 'error'); return; }
      showToast('Claim deleted.', 'success');
      return loadAppData();
    }).then(function(){ render(); });
  }

  /* =========================================================
     ACTION HANDLERS - ADMIN: STAFF / INVITES / BENEFITS / ACCESS
  ========================================================== */
  function inviteStaff(form){
    var name = form.name.value.trim();
    var email = form.email.value.trim().toLowerCase();
    var dateOfEmployment = form.dateOfEmployment.value;
    var effectiveDate = form.effectiveDate.value;
    var paynowMobile = form.paynowMobile.value.trim();
    var nric = form.nric.value.trim();
    var allocRaw = form.annualAllocation.value;
    var alloc = parseFloat(allocRaw);
    var prorateEntitlement = !!(form.prorateEntitlement && form.prorateEntitlement.checked);
    if(!name || !email || !dateOfEmployment || !effectiveDate || !paynowMobile || allocRaw==='' || isNaN(alloc)){
      showToast('Please complete all fields before adding the employee.', 'error');
      return Promise.resolve();
    }

    var familyRows = [];
    if(STATE.addEmployeeMode==='family'){
      var rowEls = form.querySelectorAll('.family-draft-row');
      for(var i=0;i<rowEls.length;i++){
        var rowEl = rowEls[i];
        var famName = rowEl.querySelector('[name="famName[]"]').value.trim();
        var famRel = rowEl.querySelector('[name="famRelationship[]"]').value;
        var famDob = rowEl.querySelector('[name="famDob[]"]').value;
        var famNric = rowEl.querySelector('[name="famNric[]"]').value.trim();
        if(!famName && !famRel && !famDob && !famNric) continue;
        if(!famName || !famRel || !famDob){
          showToast('Please complete name, relationship and date of birth for each family member (or remove the blank row).', 'error');
          return Promise.resolve();
        }
        familyRows.push({employee_email:email, name:famName, relationship:famRel, date_of_birth:famDob, nric: famNric || null});
      }
    }

    return supabase.from('invites').upsert(
      {email:email, name:name, role:'user', annual_allocation:alloc, date_of_joining:dateOfEmployment, paynow_mobile:paynowMobile, effective_date:effectiveDate, nric: nric || null, welcome_email_sent:false, invited_by:STATE.session.user.id, used:false, prorate_entitlement_default:prorateEntitlement},
      {onConflict:'email'}
    ).then(function(res){
      if(res.error) throw new Error('Could not add employee: '+res.error.message);
      if(!familyRows.length) return null;
      return supabase.from('family_members').insert(familyRows).then(function(res2){
        if(res2.error) throw new Error('Employee added, but could not add family members: '+res2.error.message);
      });
    }).then(function(){
      showToast('Added '+name+(familyRows.length?(' with '+familyRows.length+' family member'+(familyRows.length>1?'s':'')):'')+'.', 'success');
      form.reset();
      STATE.addEmployeeMode = 'single';
      return loadAppData();
    }).then(function(){ render(); }).catch(function(err){
      showToast(err.message||String(err), 'error');
      render();
    });
  }

  function handleEmployeeCsv(file){
    if(!file) return Promise.resolve();
    return file.text().then(function(text){
      var lines = text.split(/\r?\n/).map(function(l){ return l.trim(); }).filter(Boolean);
      if(lines.length<2){ showToast('CSV appears to be empty.', 'error'); return; }

      var knownEmails = {};
      STATE.profiles.forEach(function(p){ knownEmails[(p.email||'').toLowerCase()] = true; });
      STATE.invites.forEach(function(inv){ knownEmails[(inv.email||'').toLowerCase()] = true; });
      for(var pass=1; pass<lines.length; pass++){
        var pparts = lines[pass].split(',').map(function(p){ return p.trim(); });
        if((pparts[0]||'').toLowerCase()==='employee' && pparts[2]){ knownEmails[pparts[2].toLowerCase()] = true; }
      }

      var inviteRows = [];
      var familyRows = [];
      var skipped = 0;
      for(var i=1;i<lines.length;i++){
        var parts = lines[i].split(',').map(function(p){ return p.trim(); });
        var recordType = (parts[0]||'').toLowerCase();
        var name = parts[1];
        var email = (parts[2]||'').toLowerCase();
        if(recordType==='family'){
          var relationship = parts[3];
          var dateOfBirth = parts[4] && parts[4].length ? parts[4] : null;
          var nric = parts[5] && parts[5].length ? parts[5] : null;
          if(!name || !email || !relationship || !dateOfBirth || !knownEmails[email]){ skipped++; continue; }
          familyRows.push({employee_email:email, name:name, relationship:relationship, date_of_birth:dateOfBirth, nric:nric});
        } else if(recordType==='employee'){
          var nric2 = parts[5] && parts[5].length ? parts[5] : null;
          var alloc = parseFloat(parts[6])||1000;
          var dateOfJoining = parts[7] && parts[7].length ? parts[7] : null;
          var paynowMobile = parts[8] && parts[8].length ? parts[8] : null;
          var effectiveDate = parts[9] && parts[9].length ? parts[9] : null;
          // Optional 11th column: prorateEntitlement (Yes/No) pre-sets the
          // New Hire Invoicing tab's "Prorate" checkbox default for this
          // employee. Left blank, defaults to true (prorated) - same as the
          // checkbox's own default.
          var prorateRaw = parts[10] && parts[10].length ? parts[10] : null;
          var prorateEntitlementDefault = prorateRaw==null ? true : /^y/i.test(prorateRaw);
          if(!name || !email){ skipped++; continue; }
          inviteRows.push({email:email, name:name, role:'user', annual_allocation:alloc, date_of_joining:dateOfJoining, paynow_mobile:paynowMobile, effective_date:effectiveDate, nric:nric2, welcome_email_sent:false, invited_by:STATE.session.user.id, used:false, prorate_entitlement_default:prorateEntitlementDefault});
        } else {
          skipped++;
        }
      }
      if(!inviteRows.length && !familyRows.length){ showToast('No valid rows found in that CSV.', 'error'); return; }

      var chain = Promise.resolve();
      if(inviteRows.length){
        chain = chain.then(function(){ return supabase.from('invites').upsert(inviteRows, {onConflict:'email'}); }).then(function(res){
          if(res.error) throw new Error('Employee rows failed: '+res.error.message);
        });
      }
      if(familyRows.length){
        chain = chain.then(function(){ return supabase.from('family_members').insert(familyRows); }).then(function(res){
          if(res.error) throw new Error('Family rows failed: '+res.error.message);
        });
      }
      return chain.then(function(){
        var parts2 = [];
        if(inviteRows.length) parts2.push(inviteRows.length+' employee(s)');
        if(familyRows.length) parts2.push(familyRows.length+' family member(s)');
        showToast(parts2.join(' and ')+' added.'+(skipped?(' '+skipped+' row(s) skipped.'):''), 'success');
        return loadAppData();
      });
    }).then(function(){ render(); }).catch(function(err){
      showToast(err && err.message ? err.message : 'Could not read that CSV file.', 'error');
      render();
    });
  }

